pub enum WorkKind {
    Submit, Get, List, Events, Cancel, Result, Accept, Resume,
    PlanDecide, ReviewDecide, Repair, PublicationRetry, CicdStageLog,
    ApproveExternalPlanOverride, RecoverExternalReviewInfrastructure,
}
pub enum WorkCategory { Read, Control, Decision }
impl WorkKind {
    pub fn destination(&self) -> &'static str;
    pub fn category(&self) -> WorkCategory;
}
// destinations: Submit->"work.submit", Get->"work.get", List->"work.list",
//   Events->"work.events", Cancel->"work.cancel", Result->"work.result",
//   Accept->"work.accept", Resume->"work.resume",
//   PlanDecide->"work.plan_decide", ReviewDecide->"work.review_decide",
//   Repair->"work.repair", PublicationRetry->"work.publication_retry",
//   CicdStageLog->"work.cicd_stage_log",
//   ApproveExternalPlanOverride->"work.approve_external_plan_override",
//   RecoverExternalReviewInfrastructure->"work.recover_external_review_infrastructure"
// categories: Read = Get, List, Events, Result, CicdStageLog;
//   Control = Submit, Cancel, Accept, Resume;
//   Decision = PlanDecide, ReviewDecide, Repair, PublicationRetry,
//   ApproveExternalPlanOverride, RecoverExternalReviewInfrastructure
pub enum WorkPayload {
    Submit(crate::work_requests::SubmitRequest),
    Get { project_alias: String, task_id: uuid::Uuid },
    List { project_alias: String, status_filter: Option<String>,
        limit: i64, cursor_task_id: Option<uuid::Uuid>, delivery_visible: bool },
    Events { project_alias: String, task_id: uuid::Uuid, after_sequence: i64, limit: i64 },
    Cancel(crate::work_requests::CancelRequest),
    Result { project_alias: String, task_id: uuid::Uuid, attempt_id: uuid::Uuid,
        cursor: Option<String>, limit_bytes: i64 },
    Accept(crate::work_requests::AcceptRequest),
    Resume(crate::work_requests::ResumeRequest),
    PlanDecide(crate::decision_requests::PlanDecideRequest),
    ReviewDecide(crate::decision_requests::ReviewDecideRequest),
    Repair(crate::decision_requests::RepairRequest),
    PublicationRetry(crate::decision_requests::PublicationRetryRequest),
    CicdStageLog { project_alias: String, task_id: uuid::Uuid,
        correlation_id: uuid::Uuid, action_id: uuid::Uuid,
        stage_id: String, view: String, cursor_token: Option<String> },
    ApproveExternalPlanOverride(crate::decision_requests::ExternalOverrideRequest),
    RecoverExternalReviewInfrastructure(crate::decision_requests::ExternalRecoveryRequest),
}
impl forge_core::ingress::Payload for WorkPayload {
    type Kind = WorkKind;
    fn kind(&self) -> WorkKind;
}
pub fn route_key(kind: WorkKind)
    -> Result<forge_core::ingress::RouteKey, crate::work_error::WorkError>;
